package ai.eva.android.probe;
import android.content.*;import android.os.*;import rikka.shizuku.Shizuku;import java.io.*;import java.util.concurrent.*;import org.json.*;
final class PhoneShell {
 static volatile IBinder binder;static Shizuku.UserServiceArgs args;static ServiceConnection connection;
 static boolean authorized(){try{return Shizuku.pingBinder()&&Shizuku.checkSelfPermission()==0;}catch(Exception e){return false;}}
 static JSONObject status()throws Exception{JSONObject o=new JSONObject().put("authorized",authorized()).put("connected",binder!=null&&binder.isBinderAlive());try{o.put("serverRunning",Shizuku.pingBinder());if(authorized())o.put("uid",Shizuku.getUid());}catch(Exception ignored){}return o;}
 static void authorize(){if(!Shizuku.pingBinder())throw new IllegalStateException("请先安装并启动 Shizuku，再返回授权");Shizuku.requestPermission(2021);}
 static synchronized IBinder connect(Context c)throws Exception{if(!authorized())throw new IOException("Shizuku 尚未启动或未授权；普通应用没有 ADB 权限");if(binder!=null&&binder.isBinderAlive())return binder;CompletableFuture<IBinder> future=new CompletableFuture<>();args=new Shizuku.UserServiceArgs(new ComponentName(c,PhoneShellService.class)).daemon(false).processNameSuffix("phone_shell").tag("eva-phone-shell").version(69);connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){binder=b;future.complete(b);}public void onServiceDisconnected(ComponentName n){binder=null;}};Shizuku.bindUserService(args,connection);return future.get(10,TimeUnit.SECONDS);}
 static JSONObject execute(Context c,String command,long generation)throws Exception{IBinder b=connect(c);if(!PhoneAccessibility.armed||PhoneAccessibility.generation!=generation)throw new IOException("手机控制已停止");Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);in.writeString(command);if(!b.transact(1,in,out,0))throw new IOException("Shell 服务不可用");out.readException();return new JSONObject(out.readString());}finally{in.recycle();out.recycle();}}
 static int createDisplay(Context c,android.view.Surface surface,int width,int height,int dpi)throws Exception{
  IBinder b=connect(c);Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);surface.writeToParcel(in,0);in.writeInt(width);in.writeInt(height);in.writeInt(dpi);if(!b.transact(4,in,out,0))throw new IOException("后台屏服务不可用");out.readException();return out.readInt();}finally{in.recycle();out.recycle();}
 }
 static void releaseDisplay(){IBinder b=binder;if(b==null)return;Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);b.transact(5,in,out,0);out.readException();}catch(Exception ignored){}finally{in.recycle();out.recycle();}}
 static JSONObject restoreAccessibility(Context c)throws Exception{IBinder b=connect(c);if(!PhoneTaskService.keep(c))throw new IOException("已停止自动恢复");Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);in.writeString(new ComponentName(c,PhoneAccessibility.class).flattenToString());if(!b.transact(3,in,out,0))throw new IOException("恢复服务不可用");out.readException();return new JSONObject(out.readString());}finally{in.recycle();out.recycle();}}
 static void cancel(){IBinder b=binder;if(b==null)return;new Thread(()->{Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);b.transact(2,in,out,0);out.readException();}catch(Exception ignored){}finally{in.recycle();out.recycle();}}).start();}
}
